 p=w/'screenshots'/name;shutil.copy2(p,r/'captures'/name);rows.append({'file':'captures/'+name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'review':note,'accepted_finite_view':name!='rc3-reload-sky.png'})
